Object.assign(SoulbeastContent,{
STORY:()=>([{"title": "บทนำ · คำสาบานแห่งพันผนึก", "lead": "คืนที่ดวงจันทร์แตกร้าว เสียงของอสูรทุกตนเงียบลงพร้อมกัน", "text": "นครพันผนึกเคยเป็นที่ซึ่งมนุษย์และอสูรอยู่ร่วมกัน จนจอมมารปลุกหัวใจรัตติกาลขึ้นในปราสาทเหนือเหว พลังนั้นทำให้ผู้พิทักษ์พงไพรหวาดกลัวและดุร้าย ธาราเทพ ปรมาจารย์ผนึก จึงมอบผนึกแรกให้ผู้กล้าคนหนึ่ง พร้อมคำเตือนว่า «ผนึกที่แท้จริงไม่ได้เกิดจากการบังคับ แต่เกิดจากความไว้ใจ» คุณกับอสูรคู่หูต้องเดินทางผ่านห้าดินแดน ก่อนเผชิญจอมมารในด่านที่หก เพื่อพาเสียงของโลกกลับคืนมา", "quote": "จงกลับมาพร้อมสหาย มิใช่เพียงชัยชนะ", "speaker": "ธาราเทพ · ปรมาจารย์ผนึก"}, {"title": "บทที่ 1 · แสงจันทร์ที่หลงทาง", "lead": "ลำธารยังสะท้อนแสงดาว แต่ไม่มีเงาของดวงจันทร์", "text": "ป่าแสงจันทร์เป็นบ้านของอสูรตัวเล็กที่หนีความมืดจากแดนไกล ราชาทานุกิซ่อนทางออกไว้เพื่อปกป้องพวกมัน เขาเห็นผู้ผนึกทุกคนเป็นผู้รุกราน คุณต้องฝ่าทางแยกและเรียนรู้ที่จะต่อสู้เคียงข้างคู่หู ก่อนพิสูจน์ว่ามนุษย์ยังรักษาคำสัญญาได้", "after": "เมื่อราชาทานุกิยอมเปิดทาง ลำธารก็กลับมาส่องประกาย เขาชี้ไปยังหุบเขาที่เสียงกระดิ่งดังทั้งคืน: ที่นั่นมีผู้จำคืนแรกของคำสาปได้", "quote": "อสูรที่ยืนข้างเจ้าเลือกที่จะอยู่ หรือเจ้าบังคับมันกันแน่?", "speaker": "ราชาทานุกิ"}, {"title": "บทที่ 2 · กระดิ่งในม่านหมอก", "lead": "ทุกเสียงกระดิ่งพาความทรงจำหนึ่งชิ้นกลับมา", "text": "ในหุบเขาหมอกเซียน จิ้งจอกพันปีเฝ้าศาลเจ้าร้างและกักความทรงจำของผู้เดินทางไว้ในหมอก คุณพบร่องรอยว่าจอมมารเคยเป็นผู้พิทักษ์โลก แต่เลือกขโมยพลังอสูรเพื่อเอาชนะความตาย ศาลเจ้าถูกทิ้งร้างในคืนที่คำสาบานนั้นแตกหัก", "after": "หมอกแหวกออก จิ้งจอกพันปียอมคืนความทรงจำให้หุบเขา บนระฆังมีภาพสุสานทองและตาชั่งเก่าแก่ ซึ่งเป็นร่องรอยต่อไปของหัวใจรัตติกาล", "quote": "ผู้ที่กลัวการสูญเสียที่สุด อาจเป็นผู้พรากทุกสิ่งไปเสียเอง", "speaker": "จิ้งจอกพันปี"}, {"title": "บทที่ 3 · คำถามใต้สุสานทอง", "lead": "กลางผืนทราย ผู้เฝ้าประตูรอคำตอบที่ไม่ใช่คมดาบ", "text": "ทะเลทรายสุสานทองฝังเรื่องราวของอาณาจักรผู้พยายามเก็บชีวิตไว้ชั่วนิรันดร์ สฟิงซ์ผู้เฝ้าสุสานทดสอบทุกคนที่ผ่านเข้ามา บนผนังวิหาร คุณอ่านพบว่าผนึกอสูรเคยถูกสร้างขึ้นเพื่อแบ่งปันพลัง มิใช่ดึงมันออกจากเจ้าของ นี่คือความจริงที่จอมมารเลือกจะลืม", "after": "ประตูสุสานเปิดออกใต้แสงอาทิตย์ สฟิงซ์ฝากคำตอบไว้กับคุณ: พลังที่แบ่งปันจะเติบโต แต่พลังที่ช่วงชิงจะเหลือเพียงความว่างเปล่า เส้นทางถัดไปทอดขึ้นสู่ยอดเขามังกรหลับ", "quote": "หากต้องเลือก ชีวิตนิรันดร์เพียงลำพัง หรือวันธรรมดากับสหาย เจ้าจะเลือกสิ่งใด?", "speaker": "สฟิงซ์ผู้เฝ้าสุสาน"}, {"title": "บทที่ 4 · คำสาบานเหนือเมฆ", "lead": "ลมหายใจมังกรทำให้เมฆสั่น และหัวใจของคู่หูก็สั่นตาม", "text": "ยอดเขามังกรหลับถูกปกคลุมด้วยเถ้าจากคำสาป มังกรเพลิงโบราณพยายามเผาทุกเส้นทางเพื่อไม่ให้ใครขึ้นไปยังแดนสวรรค์ที่ล่มสลาย คุณต้องยืนหยัดเคียงข้างอสูรของตนในสนามรบที่สูงเหนือเมฆ และพิสูจน์ว่าความไว้ใจแข็งแกร่งกว่าความกลัว", "after": "เมื่อเปลวไฟสงบ มังกรยอมรับผู้กล้ากับสหาย มันเผยว่าหัวใจรัตติกาลหยั่งรากอยู่ในซากอาณาจักรเทพ และตราบใดที่รากยังอยู่ โลกจะไม่มีวันฟื้น", "quote": "ผู้กล้าอาจถือดาบเพียงเล่มเดียว แต่ไม่มีใครแบกโลกทั้งใบได้เพียงลำพัง", "speaker": "มังกรเพลิงโบราณ"}, {"title": "บทที่ 5 · เถ้าธุลีแห่งสวรรค์", "lead": "วิหารที่เคยอยู่เหนือดาว บัดนี้ลอยแตกสลายเหนือความมืด", "text": "แดนสวรรค์ล่มสลายยังมีเสียงสวดหลงเหลืออยู่ในเศษหิน นีดฮ็อกผู้กัดกินรากโลกกำลังดึงพลังจากดินแดนทั้งห้าไปเลี้ยงปราสาทจอมมาร คุณกับอสูรในผนึกต้องฝ่าอสูรแห่งวันสิ้นโลกเพื่อหยุดมัน ก่อนที่นครพันผนึกจะเป็นดินแดนถัดไปที่ถูกกลืน", "after": "เมื่อรากมืดขาดลง แสงจากวิหารที่แตกสลายเผยสะพานสู่ปราสาทจอมมาร เสียงของคู่หูทุกตนกลับมาชัดเจน คุณรู้แล้วว่าการต่อสู้ครั้งสุดท้ายจะเป็นการรักษาคำสาบาน มิใช่การช่วงชิงบัลลังก์", "quote": "โลกไม่ได้ต้องการเจ้าของ โลกต้องการผู้ที่ยอมดูแลมัน", "speaker": "เสียงจากวิหารที่ล่มสลาย"}, {"title": "บทที่ 6 · หัวใจแห่งรัตติกาล", "lead": "บนบัลลังก์ไร้แสง ผู้พิทักษ์คนเก่ายังคงกลัวความสูญเสีย", "text": "ปราสาทจอมมารตั้งอยู่เหนือเหวที่เต็มไปด้วยเสียงของอสูรถูกช่วงชิงพลัง จอมมารเสนอให้คุณครองโลกเคียงข้างเขา แลกกับการทิ้งอสูรคู่หูไว้เบื้องหลัง แต่คุณเดินทางมาถึงที่นี่เพราะสหายเหล่านั้น เมื่อผนึกทั้งหมดส่องแสง การต่อสู้ครั้งสุดท้ายจึงเริ่มขึ้น", "after": "หัวใจรัตติกาลแตกสลาย แสงจากผนึกคืนสู่พงไพร หุบเขา สุสาน ยอดเขา และวิหาร อสูรกลับมามีเสียงของตนเองอีกครั้ง คุณกลับสู่นครพันผนึกพร้อมสหาย ไม่มีมงกุฎรออยู่ มีเพียงประตูที่เปิดออกและผู้คนที่เรียกชื่อคุณ การเดินทางยังดำเนินต่อ แต่จากวันนี้ ทุกคำสัญญาจะถูกจดจำ", "quote": "ข้าสูญเสียทุกสิ่งเพื่อรักษาโลกไว้ เหตุใดเจ้าจึงยังเลือกความผูกพัน?", "speaker": "จอมมาร"}])
});
